    '',
    '/* ===== 信息流卡片 ===== */',
    '/* 间距/圆角/阴影/框线全走令牌,与内页卡片同一套:首页曾是 6px 缝 + 18px 角,',
    '   而 .card.m-panel 是 8px 缝 + 16px 角,同一款微博两种轮廓 */',
    '.wb-item-wrap {',
    '  /* 底部**不加**自己的外边距:站点给包装层写的显式高度本来就比卡面多 8px(实测死区 8px),',
    '     这 8px 就是可见缝。再叠 margin-bottom 会变成 16px,而内页卡是 8px —— 首页比别的页宽一倍。',
    '     左右边距照旧。 */',
    '  margin: 0 var(--bw-gutter) 0 !important;',
    '  border-radius: var(--bw-card-radius) !important;',
    '  overflow: hidden !important;',
    '  /* 框线与阴影挂在包装层上:站点把 .wb-item 撑满 wrap,而 wrap 自己 overflow:hidden,',
    '     挂在 .wb-item 上的外圈 1px 环会被 wrap 裁掉(实测整圈看不见) */',
