    ':root { --bw-btn-neutral: #e5e6eb; --bw-btn-neutral-text: #1C1C1E; }',
    '#app .profile-header:has(.m-btn-lite-white) .m-btn-lite-white {',
    '  background: var(--bw-btn-neutral) !important;',
    '  color: var(--bw-btn-neutral-text) !important;',
    '  /* 2026-09-25 复核发现边框颜色不对:border 会被算法加深改写(声明 #222222 渲染 78),',
    '     改用 inset box-shadow 画 1px 环(原值直穿,渲染 34= #222222),border 归零防双线 */',
    '  border: 0 !important;',
    '  box-shadow: inset 0 0 0 1px var(--bw-line) !important;',
